-- GENERADO por lab_baseline.py a partir de current_catalog/*.json.
-- Reconstrucción del esquema histórico para el laboratorio 5CA.
-- Sólo se ejecuta en un clúster desechable, nunca en Supabase.
SET client_min_messages = warning;
CREATE TABLE public."accion" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" character varying(50) NOT NULL,
  "descripcion" character varying(255),
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."bitacora" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "usuario_id" bigint,
  "fecha_hora" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "ip" character varying(45),
  "accion" character varying(150) NOT NULL,
  "entidad_afectada" character varying(100),
  "descripcion" text
);
CREATE TABLE public."carrito" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cliente_id" bigint NOT NULL,
  "sucursal_id" bigint NOT NULL,
  "fecha_creacion" timestamp with time zone DEFAULT now() NOT NULL,
  "estado" character varying(30) DEFAULT 'ACTIVO'::character varying NOT NULL,
  "fecha_actualizacion" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE public."categoria" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" character varying(100) NOT NULL,
  "descripcion" character varying(255),
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."ciudad" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" character varying(100) NOT NULL,
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."cliente" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "usuario_id" bigint,
  "nombre" character varying(100) NOT NULL,
  "apellido" character varying(100) NOT NULL,
  "telefono" character varying(30),
  "sexo" character varying(20),
  "ci" character varying(30),
  "fecha_nacimiento" date,
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."coleccion" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "temporada_id" bigint NOT NULL,
  "nombre" character varying(120) NOT NULL,
  "descripcion" character varying(255),
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."color" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" character varying(60) NOT NULL,
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."configuracion_vestidor_ar" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "recurso_producto_id" bigint NOT NULL,
  "zona_cuerpo" character varying(30) NOT NULL,
  "tipo_asset" character varying(20) DEFAULT 'PNG_2D'::character varying NOT NULL,
  "factor_ancho" numeric(8,4) DEFAULT 1.0000 NOT NULL,
  "factor_alto" numeric(8,4) DEFAULT 1.0000 NOT NULL,
  "offset_x" numeric(8,4) DEFAULT 0.0000 NOT NULL,
  "offset_y" numeric(8,4) DEFAULT 0.0000 NOT NULL,
  "rotacion_offset" numeric(8,2) DEFAULT 0.00 NOT NULL,
  "orden_capa" smallint DEFAULT 1 NOT NULL,
  "opacidad" numeric(5,4) DEFAULT 1.0000 NOT NULL,
  "estado" boolean DEFAULT true NOT NULL
);
CREATE TABLE public."detalle_carrito" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "carrito_id" bigint NOT NULL,
  "cantidad" integer NOT NULL,
  "inventario_id" bigint NOT NULL
);
CREATE TABLE public."detalle_devolucion" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "devolucion_id" bigint NOT NULL,
  "detalle_venta_id" bigint NOT NULL,
  "cantidad" integer NOT NULL,
  "motivo" character varying(255)
);
CREATE TABLE public."detalle_orden_compra" (
