ALTER TABLE ONLY public."inventario" ADD CONSTRAINT "ck_inventario_stock_actual" CHECK (stock_actual >= 0);
ALTER TABLE ONLY public."inventario" ADD CONSTRAINT "ck_inventario_stock_consistente" CHECK (stock_reservado <= stock_actual);
ALTER TABLE ONLY public."inventario" ADD CONSTRAINT "ck_inventario_stock_reservado" CHECK (stock_reservado >= 0);
ALTER TABLE ONLY public."movimiento_inventario" ADD CONSTRAINT "ck_movimiento_inventario_cantidad" CHECK (cantidad > 0);
ALTER TABLE ONLY public."movimiento_inventario" ADD CONSTRAINT "ck_movimiento_inventario_tipo" CHECK (tipo::text = ANY (ARRAY['ENTRADA_COMPRA'::character varying, 'SALIDA_VENTA'::character varying, 'RESERVA'::character varying, 'LIBERACION_RESERVA'::character varying, 'DEVOLUCION'::character varying, 'AJUSTE_ENTRADA'::character varying, 'AJUSTE_SALIDA'::character varying, 'TRANSFERENCIA_ENTRADA'::character varying, 'TRANSFERENCIA_SALIDA'::character varying]::text[]));
ALTER TABLE ONLY public."orden_compra" ADD CONSTRAINT "ck_orden_compra_estado" CHECK (estado::text = ANY (ARRAY['BORRADOR'::character varying, 'ENVIADA'::character varying, 'PARCIAL'::character varying, 'RECIBIDA'::character varying, 'CANCELADA'::character varying]::text[]));
ALTER TABLE ONLY public."orden_compra" ADD CONSTRAINT "ck_orden_compra_fecha_estimada" CHECK (fecha_estimada IS NULL OR fecha_estimada >= fecha_orden);
