CREATE OR REPLACE FUNCTION public.fn_actualizar_actividad_carrito()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_carrito_id bigint;
BEGIN
    v_carrito_id := COALESCE(NEW.carrito_id, OLD.carrito_id);

    UPDATE public.carrito
    SET fecha_actualizacion = NOW()
    WHERE id = v_carrito_id;

    RETURN COALESCE(NEW, OLD);
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_completar_ip_bitacora()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_ip TEXT;
BEGIN
    IF NEW.ip IS NULL OR btrim(NEW.ip) = '' THEN
        v_ip := NULLIF(current_setting('app.ip', TRUE), '');
        IF v_ip IS NOT NULL THEN
            NEW.ip := v_ip;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_controlar_actualizacion_inventario()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NEW.sucursal_id IS DISTINCT FROM OLD.sucursal_id
       OR NEW.variante_producto_id IS DISTINCT FROM OLD.variante_producto_id
       OR NEW.temporada_id IS DISTINCT FROM OLD.temporada_id THEN
        RAISE EXCEPTION 'No se puede cambiar la sucursal, variante o temporada de un inventario existente';
    END IF;
    IF NEW.stock_actual IS DISTINCT FROM OLD.stock_actual
       OR NEW.stock_reservado IS DISTINCT FROM OLD.stock_reservado THEN
        NEW.fecha_actualizacion := CURRENT_TIMESTAMP;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_normalizar_correo_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NEW.correo IS NULL OR BTRIM(NEW.correo) = '' THEN
        RAISE EXCEPTION 'El correo del usuario no puede estar vacío';
    END IF;
    NEW.correo := LOWER(BTRIM(NEW.correo));
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_normalizar_sku()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF NEW.sku IS NULL OR BTRIM(NEW.sku) = '' THEN
        RAISE EXCEPTION 'El SKU de una variante no puede estar vacío';
    END IF;
    NEW.sku := UPPER(BTRIM(NEW.sku));
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_proteger_detalle_orden_compra()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_orden_id BIGINT;
    v_estado VARCHAR(30);
BEGIN
    IF TG_OP = 'DELETE' THEN v_orden_id := OLD.orden_compra_id; ELSE v_orden_id := NEW.orden_compra_id; END IF;
    SELECT estado INTO v_estado FROM orden_compra WHERE id = v_orden_id;
    IF FOUND AND v_estado IN ('RECIBIDA','CANCELADA') THEN
        RAISE EXCEPTION 'No se pueden modificar los detalles de la orden % porque está en estado %', v_orden_id, v_estado;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_proteger_detalle_venta()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_venta_id BIGINT;
    v_estado VARCHAR(30);
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_venta_id := OLD.venta_id;
    ELSE
        v_venta_id := NEW.venta_id;
    END IF;
    SELECT estado INTO v_estado FROM venta WHERE id = v_venta_id;
    IF FOUND AND v_estado IN ('COMPLETADA','CANCELADA','REEMBOLSADA') THEN
        RAISE EXCEPTION 'No se pueden modificar los detalles de la venta % porque está en estado %', v_venta_id, v_estado;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_proteger_eliminacion_venta()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF OLD.estado IN ('PAGADA','COMPLETADA','REEMBOLSADA') THEN
        RAISE EXCEPTION 'No se puede eliminar la venta % porque está en estado %', OLD.id, OLD.estado;
    END IF;
    RETURN OLD;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_recalcular_total_venta_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_venta_id BIGINT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_venta_id := OLD.venta_id;
        UPDATE venta SET total = (SELECT COALESCE(SUM(cantidad * precio_unitario),0) FROM detalle_venta WHERE venta_id = v_venta_id) WHERE id = v_venta_id;
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.venta_id IS DISTINCT FROM NEW.venta_id THEN
            UPDATE venta SET total = (SELECT COALESCE(SUM(cantidad * precio_unitario),0) FROM detalle_venta WHERE venta_id = OLD.venta_id) WHERE id = OLD.venta_id;
        END IF;
        v_venta_id := NEW.venta_id;
    ELSE
        v_venta_id := NEW.venta_id;
    END IF;
    UPDATE venta SET total = (SELECT COALESCE(SUM(cantidad * precio_unitario),0) FROM detalle_venta WHERE venta_id = v_venta_id) WHERE id = v_venta_id;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_registrar_bitacora()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_usuario_text TEXT;
    v_usuario_id BIGINT;
    v_registro_id TEXT;
    v_accion TEXT;
BEGIN
    v_usuario_text := current_setting('app.usuario_id', TRUE);
    IF v_usuario_text IS NOT NULL AND v_usuario_text ~ '^[0-9]+$' THEN
        v_usuario_id := v_usuario_text::BIGINT;
    ELSE
        v_usuario_id := NULL;
    END IF;
    CASE TG_OP
        WHEN 'INSERT' THEN v_accion := 'CREAR'; v_registro_id := NEW.id::TEXT;
        WHEN 'UPDATE' THEN v_accion := 'MODIFICAR'; v_registro_id := NEW.id::TEXT;
        WHEN 'DELETE' THEN v_accion := 'ELIMINAR'; v_registro_id := OLD.id::TEXT;
        ELSE v_accion := TG_OP;
    END CASE;
    INSERT INTO bitacora (usuario_id, fecha_hora, accion, entidad_afectada, descripcion)
    VALUES (v_usuario_id, CURRENT_TIMESTAMP, v_accion, TG_TABLE_NAME,
            FORMAT('Operación %s sobre registro ID %s', v_accion, v_registro_id));
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_validar_detalle_devolucion()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_venta_devolucion BIGINT;
    v_venta_detalle BIGINT;
    v_cantidad_vendida INTEGER;
BEGIN
    SELECT venta_id INTO v_venta_devolucion FROM devolucion WHERE id = NEW.devolucion_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'La devolución % no existe', NEW.devolucion_id; END IF;
    SELECT venta_id, cantidad INTO v_venta_detalle, v_cantidad_vendida FROM detalle_venta WHERE id = NEW.detalle_venta_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'El detalle de venta % no existe', NEW.detalle_venta_id; END IF;
    IF v_venta_devolucion <> v_venta_detalle THEN
        RAISE EXCEPTION 'El detalle de venta % no pertenece a la venta asociada a la devolución %', NEW.detalle_venta_id, NEW.devolucion_id;
    END IF;
    IF NEW.cantidad > v_cantidad_vendida THEN
        RAISE EXCEPTION 'No se pueden devolver % unidades. Solo se vendieron %.', NEW.cantidad, v_cantidad_vendida;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_validar_detalle_reserva_sucursal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_sucursal_reserva BIGINT;
    v_sucursal_inventario BIGINT;
BEGIN
    SELECT sucursal_id INTO v_sucursal_reserva FROM reserva WHERE id = NEW.reserva_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'La reserva % no existe', NEW.reserva_id;
    END IF;
    SELECT sucursal_id INTO v_sucursal_inventario FROM inventario WHERE id = NEW.inventario_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El inventario % no existe', NEW.inventario_id;
    END IF;
    IF v_sucursal_reserva <> v_sucursal_inventario THEN
        RAISE EXCEPTION 'El inventario % no pertenece a la sucursal de la reserva %', NEW.inventario_id, NEW.reserva_id;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_validar_detalle_venta_sucursal()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_sucursal_venta BIGINT;
    v_sucursal_inventario BIGINT;
BEGIN
    SELECT sucursal_id INTO v_sucursal_venta FROM venta WHERE id = NEW.venta_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'La venta % no existe', NEW.venta_id;
    END IF;
    SELECT sucursal_id INTO v_sucursal_inventario FROM inventario WHERE id = NEW.inventario_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'El inventario % no existe', NEW.inventario_id;
    END IF;
    IF v_sucursal_venta <> v_sucursal_inventario THEN
        RAISE EXCEPTION 'El inventario % pertenece a una sucursal diferente a la venta %', NEW.inventario_id, NEW.venta_id;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_validar_producto_proveedor_orden()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_proveedor_id BIGINT;
    v_producto_id BIGINT;
BEGIN
    SELECT proveedor_id INTO v_proveedor_id FROM orden_compra WHERE id = NEW.orden_compra_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'La orden de compra % no existe', NEW.orden_compra_id; END IF;
    SELECT producto_id INTO v_producto_id FROM variante_producto WHERE id = NEW.variante_producto_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'La variante % no existe', NEW.variante_producto_id; END IF;
    IF NOT EXISTS (SELECT 1 FROM proveedor_producto WHERE proveedor_id = v_proveedor_id AND producto_id = v_producto_id AND estado = TRUE) THEN
        RAISE EXCEPTION 'El producto % no está asociado al proveedor %', v_producto_id, v_proveedor_id;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.fn_validar_sucursal_detalle_carrito()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_sucursal_carrito bigint;
    v_sucursal_inventario bigint;
BEGIN
    SELECT sucursal_id
    INTO v_sucursal_carrito
    FROM public.carrito
    WHERE id = NEW.carrito_id;

    SELECT sucursal_id
    INTO v_sucursal_inventario
    FROM public.inventario
    WHERE id = NEW.inventario_id;

    IF v_sucursal_carrito IS NULL THEN
        RAISE EXCEPTION 'Carrito inexistente';
    END IF;

    IF v_sucursal_inventario IS NULL THEN
        RAISE EXCEPTION 'Inventario inexistente';
    END IF;

    IF v_sucursal_carrito <> v_sucursal_inventario THEN
        RAISE EXCEPTION
            'El inventario seleccionado no pertenece a la sucursal del carrito';
    END IF;

    RETURN NEW;
END;
$function$;
CREATE OR REPLACE PROCEDURE public.sp_ajustar_inventario(IN p_inventario_id bigint, IN p_tipo character varying, IN p_cantidad integer, IN p_usuario_id bigint, IN p_observacion text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_inventario RECORD;
    v_disponible INTEGER;
BEGIN
    IF p_tipo NOT IN ('AJUSTE_ENTRADA', 'AJUSTE_SALIDA') THEN
        RAISE EXCEPTION 'Tipo de ajuste no válido: %', p_tipo;
    END IF;

    IF p_cantidad <= 0 THEN
        RAISE EXCEPTION 'La cantidad debe ser mayor que cero';
    END IF;

    IF p_observacion IS NULL OR LENGTH(TRIM(p_observacion)) = 0 THEN
        RAISE EXCEPTION 'Todo ajuste de inventario debe incluir una observación';
    END IF;

    SELECT * INTO v_inventario
    FROM inventario
    WHERE id = p_inventario_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Inventario % no encontrado', p_inventario_id;
    END IF;

    IF p_tipo = 'AJUSTE_ENTRADA' THEN
        UPDATE inventario
        SET stock_actual = stock_actual + p_cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = p_inventario_id;
    ELSE
        v_disponible := v_inventario.stock_actual - v_inventario.stock_reservado;

        IF v_disponible < p_cantidad THEN
            RAISE EXCEPTION 'No se puede retirar %. Stock disponible: %. Existen % unidades reservadas.',
                p_cantidad, v_disponible, v_inventario.stock_reservado;
        END IF;

        UPDATE inventario
        SET stock_actual = stock_actual - p_cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = p_inventario_id;
    END IF;

    INSERT INTO movimiento_inventario (
        inventario_id, usuario_id, tipo, cantidad, fecha_hora,
        observaciones, referencia_tipo, referencia_id
    ) VALUES (
        p_inventario_id, p_usuario_id, p_tipo, p_cantidad,
        CURRENT_TIMESTAMP, p_observacion, 'AJUSTE', NULL
    );
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_cancelar_reserva(IN p_reserva_id bigint, IN p_usuario_id bigint, IN p_observacion text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_reserva RECORD;
    v_detalle RECORD;
BEGIN
    SELECT * INTO v_reserva
    FROM reserva
    WHERE id = p_reserva_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La reserva % no existe', p_reserva_id;
    END IF;

    IF v_reserva.estado NOT IN ('PENDIENTE', 'CONFIRMADA') THEN
        RAISE EXCEPTION 'La reserva % no puede cancelarse porque se encuentra en estado %', p_reserva_id, v_reserva.estado;
    END IF;

    FOR v_detalle IN
        SELECT dr.inventario_id, dr.cantidad
        FROM detalle_reserva dr
        WHERE dr.reserva_id = p_reserva_id
        ORDER BY dr.inventario_id
    LOOP
        PERFORM 1 FROM inventario WHERE id = v_detalle.inventario_id FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Inventario % de la reserva no encontrado', v_detalle.inventario_id;
        END IF;

        IF (SELECT stock_reservado FROM inventario WHERE id = v_detalle.inventario_id) < v_detalle.cantidad THEN
            RAISE EXCEPTION 'Inconsistencia en stock reservado del inventario %', v_detalle.inventario_id;
        END IF;

        UPDATE inventario
        SET stock_reservado = stock_reservado - v_detalle.cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = v_detalle.inventario_id;

        INSERT INTO movimiento_inventario (
            inventario_id, usuario_id, tipo, cantidad, fecha_hora,
            observaciones, referencia_tipo, referencia_id
        ) VALUES (
            v_detalle.inventario_id, p_usuario_id, 'LIBERACION_RESERVA',
            v_detalle.cantidad, CURRENT_TIMESTAMP,
            COALESCE(p_observacion, 'Reserva cancelada'), 'RESERVA', p_reserva_id
        );
    END LOOP;

    UPDATE reserva
    SET estado = 'CANCELADA',
        observacion = CASE
            WHEN p_observacion IS NULL THEN observacion
            WHEN observacion IS NULL THEN p_observacion
            ELSE observacion || ' | ' || p_observacion
        END
    WHERE id = p_reserva_id;
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_confirmar_venta(IN p_venta_id bigint, IN p_usuario_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_venta RECORD;
    v_detalle RECORD;
    v_inventario RECORD;
    v_cantidad_reservada INTEGER;
    v_consumo_reserva INTEGER;
    v_cantidad_directa INTEGER;
    v_reserva_detalle RECORD;
    v_vendido INTEGER;
    v_consumido INTEGER;
    v_liberar INTEGER;
    v_total NUMERIC(12,2);
BEGIN
    SELECT * INTO v_venta
    FROM venta
    WHERE id = p_venta_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La venta % no existe', p_venta_id;
    END IF;

    IF v_venta.estado NOT IN ('PENDIENTE', 'PAGADA') THEN
        RAISE EXCEPTION 'La venta % no puede confirmarse porque está en estado %', p_venta_id, v_venta.estado;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM detalle_venta WHERE venta_id = p_venta_id) THEN
        RAISE EXCEPTION 'La venta % no contiene productos', p_venta_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pago WHERE venta_id = p_venta_id AND estado = 'APROBADO') THEN
        RAISE EXCEPTION 'La venta % no posee un pago aprobado', p_venta_id;
    END IF;

    IF v_venta.reserva_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM reserva
            WHERE id = v_venta.reserva_id
              AND estado IN ('PENDIENTE', 'CONFIRMADA')
              AND sucursal_id = v_venta.sucursal_id
        ) THEN
            RAISE EXCEPTION 'La reserva asociada a la venta no es válida';
        END IF;
    END IF;

    FOR v_detalle IN
        SELECT * FROM detalle_venta
        WHERE venta_id = p_venta_id
        ORDER BY inventario_id
    LOOP
        SELECT * INTO v_inventario
        FROM inventario
        WHERE id = v_detalle.inventario_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Inventario % no encontrado', v_detalle.inventario_id;
        END IF;

        IF v_inventario.sucursal_id <> v_venta.sucursal_id THEN
            RAISE EXCEPTION 'El producto del inventario % pertenece a otra sucursal', v_detalle.inventario_id;
        END IF;

        v_cantidad_reservada := 0;

        IF v_venta.reserva_id IS NOT NULL THEN
            SELECT COALESCE((
                SELECT cantidad
                FROM detalle_reserva
                WHERE reserva_id = v_venta.reserva_id
                  AND inventario_id = v_detalle.inventario_id
            ), 0)
            INTO v_cantidad_reservada;
        END IF;

        v_consumo_reserva := LEAST(v_cantidad_reservada, v_detalle.cantidad);
        v_cantidad_directa := v_detalle.cantidad - v_consumo_reserva;

        IF v_inventario.stock_actual < v_detalle.cantidad THEN
            RAISE EXCEPTION 'Stock físico insuficiente en inventario %. Disponible físico: %, solicitado: %',
                v_detalle.inventario_id, v_inventario.stock_actual, v_detalle.cantidad;
        END IF;

        IF (v_inventario.stock_actual - v_inventario.stock_reservado) < v_cantidad_directa THEN
            RAISE EXCEPTION 'Stock disponible insuficiente para inventario %. Cantidad adicional requerida: %',
                v_detalle.inventario_id, v_cantidad_directa;
        END IF;

        IF v_inventario.stock_reservado < v_consumo_reserva THEN
            RAISE EXCEPTION 'Existe inconsistencia en el stock reservado del inventario %', v_detalle.inventario_id;
        END IF;

        UPDATE inventario
        SET stock_actual = stock_actual - v_detalle.cantidad,
            stock_reservado = stock_reservado - v_consumo_reserva,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = v_detalle.inventario_id;

        INSERT INTO movimiento_inventario (
            inventario_id, usuario_id, tipo, cantidad, fecha_hora,
            observaciones, referencia_tipo, referencia_id
        ) VALUES (
            v_detalle.inventario_id, p_usuario_id, 'SALIDA_VENTA',
            v_detalle.cantidad, CURRENT_TIMESTAMP,
            'Salida de inventario por venta', 'VENTA', p_venta_id
        );
    END LOOP;

    IF v_venta.reserva_id IS NOT NULL THEN
        FOR v_reserva_detalle IN
            SELECT * FROM detalle_reserva
            WHERE reserva_id = v_venta.reserva_id
            ORDER BY inventario_id
        LOOP
            SELECT COALESCE(SUM(cantidad), 0)
            INTO v_vendido
            FROM detalle_venta
            WHERE venta_id = p_venta_id
              AND inventario_id = v_reserva_detalle.inventario_id;

            v_consumido := LEAST(v_reserva_detalle.cantidad, v_vendido);
            v_liberar := v_reserva_detalle.cantidad - v_consumido;

            IF v_liberar > 0 THEN
                PERFORM 1
                FROM inventario
                WHERE id = v_reserva_detalle.inventario_id
                FOR UPDATE;

                IF (SELECT stock_reservado FROM inventario WHERE id = v_reserva_detalle.inventario_id) < v_liberar THEN
                    RAISE EXCEPTION 'Inconsistencia al liberar inventario reservado %', v_reserva_detalle.inventario_id;
                END IF;

                UPDATE inventario
                SET stock_reservado = stock_reservado - v_liberar,
                    fecha_actualizacion = CURRENT_TIMESTAMP
                WHERE id = v_reserva_detalle.inventario_id;

                INSERT INTO movimiento_inventario (
                    inventario_id, usuario_id, tipo, cantidad, fecha_hora,
                    observaciones, referencia_tipo, referencia_id
                ) VALUES (
                    v_reserva_detalle.inventario_id, p_usuario_id,
                    'LIBERACION_RESERVA', v_liberar, CURRENT_TIMESTAMP,
                    'Prenda reservada no adquirida durante la venta',
                    'RESERVA', v_venta.reserva_id
                );
            END IF;
        END LOOP;

        UPDATE reserva SET estado = 'ATENDIDA' WHERE id = v_venta.reserva_id;
    END IF;

    SELECT COALESCE(SUM(cantidad * precio_unitario), 0)
    INTO v_total
    FROM detalle_venta
    WHERE venta_id = p_venta_id;

    UPDATE venta
    SET total = v_total,
        estado = 'COMPLETADA'
    WHERE id = p_venta_id;
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_crear_reserva_desde_carrito(IN p_carrito_id bigint, IN p_fecha_atencion timestamp with time zone, IN p_observacion text, IN p_usuario_id bigint, INOUT p_reserva_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_carrito RECORD;
    v_detalle RECORD;
    v_inventario RECORD;
    v_stock_disponible INTEGER;
BEGIN
    ------------------------------------------------------------------
    -- 1. Validaciones básicas
    ------------------------------------------------------------------

    IF p_fecha_atencion <= CURRENT_TIMESTAMP THEN
        RAISE EXCEPTION
            'La fecha de atención debe ser posterior a la fecha actual';
    END IF;

    ------------------------------------------------------------------
    -- 2. Bloquear carrito para impedir doble conversión concurrente
    ------------------------------------------------------------------

    SELECT
        c.id,
        c.cliente_id,
        c.sucursal_id,
        c.estado,
        c.fecha_actualizacion
    INTO v_carrito
    FROM carrito c
    WHERE c.id = p_carrito_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'El carrito % no existe', p_carrito_id;
    END IF;

    IF v_carrito.estado <> 'ACTIVO' THEN
        RAISE EXCEPTION
            'El carrito % no se encuentra activo', p_carrito_id;
    END IF;

    ------------------------------------------------------------------
    -- 3. Validar cliente y sucursal
    ------------------------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM cliente
        WHERE id = v_carrito.cliente_id
          AND estado = TRUE
    ) THEN
        RAISE EXCEPTION
            'El cliente asociado al carrito no existe o está inactivo';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM sucursal
        WHERE id = v_carrito.sucursal_id
          AND estado = TRUE
    ) THEN
        RAISE EXCEPTION
            'La sucursal asociada al carrito no existe o está inactiva';
    END IF;

    ------------------------------------------------------------------
    -- 4. Validar que tenga prendas
    ------------------------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM detalle_carrito
        WHERE carrito_id = p_carrito_id
    ) THEN
        RAISE EXCEPTION
            'El carrito no contiene prendas para reservar';
    END IF;

    ------------------------------------------------------------------
    -- 5. Crear reserva vinculada al carrito
    ------------------------------------------------------------------

    INSERT INTO reserva (
        cliente_id,
        sucursal_id,
        carrito_id,
        fecha_reserva,
        fecha_atencion,
        estado,
        observacion
    )
    VALUES (
        v_carrito.cliente_id,
        v_carrito.sucursal_id,
        p_carrito_id,
        CURRENT_TIMESTAMP,
        p_fecha_atencion,
        'PENDIENTE',
        p_observacion
    )
    RETURNING id INTO p_reserva_id;

    ------------------------------------------------------------------
    -- 6. Procesar las prendas reales del carrito
    ------------------------------------------------------------------

    FOR v_detalle IN
        SELECT
            dc.inventario_id,
            dc.cantidad
        FROM detalle_carrito dc
        WHERE dc.carrito_id = p_carrito_id
        ORDER BY dc.inventario_id
    LOOP

        IF v_detalle.cantidad IS NULL OR v_detalle.cantidad <= 0 THEN
            RAISE EXCEPTION
                'Existe una cantidad inválida en el carrito';
        END IF;

        --------------------------------------------------------------
        -- Bloqueo de inventario para concurrencia
        --------------------------------------------------------------

        SELECT
            i.id,
            i.sucursal_id,
            i.stock_actual,
            i.stock_reservado
        INTO v_inventario
        FROM inventario i
        WHERE i.id = v_detalle.inventario_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'No existe el inventario %',
                v_detalle.inventario_id;
        END IF;

        IF v_inventario.sucursal_id <> v_carrito.sucursal_id THEN
            RAISE EXCEPTION
                'El inventario % no pertenece a la sucursal del carrito',
                v_detalle.inventario_id;
        END IF;

        v_stock_disponible :=
            v_inventario.stock_actual
            - v_inventario.stock_reservado;

        IF v_stock_disponible < v_detalle.cantidad THEN
            RAISE EXCEPTION
                'Stock insuficiente para inventario %. Disponible: %, solicitado: %',
                v_detalle.inventario_id,
                v_stock_disponible,
                v_detalle.cantidad;
        END IF;

        --------------------------------------------------------------
        -- Reservar stock
        --------------------------------------------------------------

        UPDATE inventario
        SET
            stock_reservado =
                stock_reservado + v_detalle.cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = v_detalle.inventario_id;

        --------------------------------------------------------------
        -- Detalle de reserva
        --------------------------------------------------------------

        INSERT INTO detalle_reserva (
            reserva_id,
            inventario_id,
            cantidad
        )
        VALUES (
            p_reserva_id,
            v_detalle.inventario_id,
            v_detalle.cantidad
        );

        --------------------------------------------------------------
        -- Kardex
        --------------------------------------------------------------

        INSERT INTO movimiento_inventario (
            inventario_id,
            usuario_id,
            tipo,
            cantidad,
            fecha_hora,
            observaciones,
            referencia_tipo,
            referencia_id
        )
        VALUES (
            v_detalle.inventario_id,
            p_usuario_id,
            'RESERVA',
            v_detalle.cantidad,
            CURRENT_TIMESTAMP,
            'Stock reservado para cliente',
            'RESERVA',
            p_reserva_id
        );

    END LOOP;

    ------------------------------------------------------------------
    -- 7. Carrito consumido por la reserva
    ------------------------------------------------------------------

    UPDATE carrito
    SET
        estado = 'CONVERTIDO',
        fecha_actualizacion = CURRENT_TIMESTAMP
    WHERE id = p_carrito_id;

END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_crear_reserva(IN p_cliente_id bigint, IN p_sucursal_id bigint, IN p_fecha_atencion timestamp with time zone, IN p_observacion text, IN p_items jsonb, IN p_usuario_id bigint, INOUT p_reserva_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_item RECORD;
    v_inventario RECORD;
    v_stock_disponible INTEGER;
BEGIN
    IF p_fecha_atencion <= CURRENT_TIMESTAMP THEN
        RAISE EXCEPTION 'La fecha de atención debe ser posterior a la fecha actual';
    END IF;

    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'La reserva debe contener al menos una prenda';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM cliente WHERE id = p_cliente_id AND estado = TRUE) THEN
        RAISE EXCEPTION 'El cliente % no existe o está inactivo', p_cliente_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM sucursal WHERE id = p_sucursal_id AND estado = TRUE) THEN
        RAISE EXCEPTION 'La sucursal % no existe o está inactiva', p_sucursal_id;
    END IF;

    INSERT INTO reserva (cliente_id, sucursal_id, fecha_reserva, fecha_atencion, estado, observacion)
    VALUES (p_cliente_id, p_sucursal_id, CURRENT_TIMESTAMP, p_fecha_atencion, 'PENDIENTE', p_observacion)
    RETURNING id INTO p_reserva_id;

    FOR v_item IN
        SELECT inventario_id, SUM(cantidad)::INTEGER AS cantidad
        FROM jsonb_to_recordset(p_items) AS x(inventario_id BIGINT, cantidad INTEGER)
        GROUP BY inventario_id
        ORDER BY inventario_id
    LOOP
        IF v_item.cantidad IS NULL OR v_item.cantidad <= 0 THEN
            RAISE EXCEPTION 'La cantidad de una reserva debe ser mayor que cero';
        END IF;

        SELECT i.id, i.sucursal_id, i.stock_actual, i.stock_reservado, i.variante_producto_id, i.temporada_id
        INTO v_inventario
        FROM inventario i
        WHERE i.id = v_item.inventario_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'No existe el inventario %', v_item.inventario_id;
        END IF;

        IF v_inventario.sucursal_id <> p_sucursal_id THEN
            RAISE EXCEPTION 'El inventario % no pertenece a la sucursal de la reserva', v_item.inventario_id;
        END IF;

        v_stock_disponible := v_inventario.stock_actual - v_inventario.stock_reservado;

        IF v_stock_disponible < v_item.cantidad THEN
            RAISE EXCEPTION 'Stock insuficiente para inventario %. Disponible: %, solicitado: %',
                v_item.inventario_id, v_stock_disponible, v_item.cantidad;
        END IF;

        UPDATE inventario
        SET stock_reservado = stock_reservado + v_item.cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = v_item.inventario_id;

        INSERT INTO detalle_reserva (reserva_id, inventario_id, cantidad)
        VALUES (p_reserva_id, v_item.inventario_id, v_item.cantidad);

        INSERT INTO movimiento_inventario (
            inventario_id, usuario_id, tipo, cantidad, fecha_hora,
            observaciones, referencia_tipo, referencia_id
        ) VALUES (
            v_item.inventario_id, p_usuario_id, 'RESERVA', v_item.cantidad,
            CURRENT_TIMESTAMP, 'Stock reservado para cliente', 'RESERVA', p_reserva_id
        );
    END LOOP;
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_finalizar_reserva_sin_compra(IN p_reserva_id bigint, IN p_usuario_id bigint, IN p_observacion text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_reserva RECORD;
    v_detalle RECORD;
    v_stock_reservado INTEGER;
BEGIN
    -- 1. Bloquear la reserva para evitar que otro proceso
    --    la modifique al mismo tiempo.
    SELECT *
    INTO v_reserva
    FROM reserva
    WHERE id = p_reserva_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La reserva % no existe', p_reserva_id;
    END IF;

    -- 2. CU18 solo puede finalizar sin compra
    --    una reserva previamente CONFIRMADA.
    IF v_reserva.estado <> 'CONFIRMADA' THEN
        RAISE EXCEPTION
            'La reserva % no puede finalizarse sin compra porque se encuentra en estado %',
            p_reserva_id,
            v_reserva.estado;
    END IF;

    -- 3. La reserva debe tener prendas asociadas.
    IF NOT EXISTS (
        SELECT 1
        FROM detalle_reserva
        WHERE reserva_id = p_reserva_id
    ) THEN
        RAISE EXCEPTION
            'La reserva % no contiene prendas reservadas',
            p_reserva_id;
    END IF;

    -- 4. Recorrer todas las prendas reservadas.
    --    El ORDER BY mantiene siempre el mismo orden de bloqueo.
    FOR v_detalle IN
        SELECT
            dr.inventario_id,
            dr.cantidad
        FROM detalle_reserva dr
        WHERE dr.reserva_id = p_reserva_id
        ORDER BY dr.inventario_id
    LOOP
        -- Bloquear inventario.
        SELECT stock_reservado
        INTO v_stock_reservado
        FROM inventario
        WHERE id = v_detalle.inventario_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'Inventario % de la reserva no encontrado',
                v_detalle.inventario_id;
        END IF;

        -- Validar consistencia antes de liberar.
        IF v_stock_reservado < v_detalle.cantidad THEN
            RAISE EXCEPTION
                'Inconsistencia en stock reservado del inventario %. Reservado: %, requerido para liberar: %',
                v_detalle.inventario_id,
                v_stock_reservado,
                v_detalle.cantidad;
        END IF;

        -- 5. Liberar únicamente stock_reservado.
        --    stock_actual NO se modifica.
        UPDATE inventario
        SET
            stock_reservado = stock_reservado - v_detalle.cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = v_detalle.inventario_id;

        -- 6. Registrar trazabilidad.
        INSERT INTO movimiento_inventario (
            inventario_id,
            usuario_id,
            tipo,
            cantidad,
            fecha_hora,
            observaciones,
            referencia_tipo,
            referencia_id
        )
        VALUES (
            v_detalle.inventario_id,
            p_usuario_id,
            'LIBERACION_RESERVA',
            v_detalle.cantidad,
            CURRENT_TIMESTAMP,
            COALESCE(
                NULLIF(TRIM(p_observacion), ''),
                'Atención finalizada sin compra'
            ),
            'RESERVA',
            p_reserva_id
        );
    END LOOP;

    -- 7. La reserva sí fue atendida, aunque el cliente no compró.
    UPDATE reserva
    SET
        estado = 'ATENDIDA',

        -- No sobrescribimos la observación original del cliente.
        -- Solo agregamos la nueva si realmente se recibió una.
        observacion = CASE
            WHEN p_observacion IS NULL
                 OR TRIM(p_observacion) = ''
                THEN observacion

            WHEN observacion IS NULL
                 OR TRIM(observacion) = ''
                THEN p_observacion

            ELSE observacion || ' | ' || p_observacion
        END
    WHERE id = p_reserva_id;
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_recalcular_total_venta(IN p_venta_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_total NUMERIC(12,2);
BEGIN
    IF NOT EXISTS (SELECT 1 FROM venta WHERE id = p_venta_id) THEN
        RAISE EXCEPTION 'La venta % no existe', p_venta_id;
    END IF;

    SELECT COALESCE(SUM(cantidad * precio_unitario), 0)
    INTO v_total
    FROM detalle_venta
    WHERE venta_id = p_venta_id;

    UPDATE venta SET total = v_total WHERE id = p_venta_id;
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_recibir_orden_compra(IN p_orden_compra_id bigint, IN p_usuario_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_orden RECORD;
    v_detalle RECORD;
    v_inventario_id BIGINT;
BEGIN
    SELECT * INTO v_orden
    FROM orden_compra
    WHERE id = p_orden_compra_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La orden de compra % no existe', p_orden_compra_id;
    END IF;

    IF v_orden.estado NOT IN ('ENVIADA', 'PARCIAL') THEN
        RAISE EXCEPTION 'La orden de compra % no puede recibirse porque está en estado %', p_orden_compra_id, v_orden.estado;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM detalle_orden_compra WHERE orden_compra_id = p_orden_compra_id) THEN
        RAISE EXCEPTION 'La orden de compra % no contiene productos', p_orden_compra_id;
    END IF;

    FOR v_detalle IN
        SELECT * FROM detalle_orden_compra
        WHERE orden_compra_id = p_orden_compra_id
        ORDER BY variante_producto_id, temporada_id
    LOOP
        INSERT INTO inventario (
            sucursal_id, variante_producto_id, temporada_id,
            stock_actual, stock_reservado, fecha_actualizacion
        ) VALUES (
            v_orden.sucursal_id, v_detalle.variante_producto_id,
            v_detalle.temporada_id, v_detalle.cantidad, 0,
            CURRENT_TIMESTAMP
        )
        ON CONFLICT (sucursal_id, variante_producto_id, temporada_id)
        DO UPDATE SET
            stock_actual = inventario.stock_actual + EXCLUDED.stock_actual,
            fecha_actualizacion = CURRENT_TIMESTAMP
        RETURNING id INTO v_inventario_id;

        INSERT INTO movimiento_inventario (
            inventario_id, usuario_id, tipo, cantidad, fecha_hora,
            observaciones, referencia_tipo, referencia_id
        ) VALUES (
            v_inventario_id, p_usuario_id, 'ENTRADA_COMPRA',
            v_detalle.cantidad, CURRENT_TIMESTAMP,
            'Recepción de orden de compra', 'ORDEN_COMPRA', p_orden_compra_id
        );
    END LOOP;

    UPDATE orden_compra
    SET estado = 'RECIBIDA',
        fecha_recepcion = CURRENT_TIMESTAMP
    WHERE id = p_orden_compra_id;
END;
$procedure$;
CREATE OR REPLACE PROCEDURE public.sp_registrar_devolucion(IN p_devolucion_id bigint, IN p_usuario_id bigint)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $procedure$
DECLARE
    v_devolucion RECORD;
    v_detalle RECORD;
    v_cantidad_vendida INTEGER;
    v_devuelto_previamente INTEGER;
    v_inventario_id BIGINT;
BEGIN
    SELECT * INTO v_devolucion
    FROM devolucion
    WHERE id = p_devolucion_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'La devolución % no existe', p_devolucion_id;
    END IF;

    IF v_devolucion.estado <> 'APROBADA' THEN
        RAISE EXCEPTION 'La devolución % debe estar APROBADA antes de procesarse. Estado actual: %',
            p_devolucion_id, v_devolucion.estado;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM detalle_devolucion WHERE devolucion_id = p_devolucion_id) THEN
        RAISE EXCEPTION 'La devolución % no contiene productos', p_devolucion_id;
    END IF;

    FOR v_detalle IN
        SELECT * FROM detalle_devolucion
        WHERE devolucion_id = p_devolucion_id
        ORDER BY detalle_venta_id
    LOOP
        SELECT dv.cantidad, dv.inventario_id
        INTO v_cantidad_vendida, v_inventario_id
        FROM detalle_venta dv
        WHERE dv.id = v_detalle.detalle_venta_id
          AND dv.venta_id = v_devolucion.venta_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'El detalle de venta % no pertenece a la venta de esta devolución',
                v_detalle.detalle_venta_id;
        END IF;

        SELECT COALESCE(SUM(dd.cantidad), 0)
        INTO v_devuelto_previamente
        FROM detalle_devolucion dd
        INNER JOIN devolucion d ON d.id = dd.devolucion_id
        WHERE dd.detalle_venta_id = v_detalle.detalle_venta_id
          AND d.id <> p_devolucion_id
          AND d.estado IN ('APROBADA', 'COMPLETADA');

        IF (v_devuelto_previamente + v_detalle.cantidad) > v_cantidad_vendida THEN
            RAISE EXCEPTION 'No se pueden devolver % unidades. Vendidas: %, ya devueltas: %',
                v_detalle.cantidad, v_cantidad_vendida, v_devuelto_previamente;
        END IF;

        PERFORM 1 FROM inventario WHERE id = v_inventario_id FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Inventario % no encontrado', v_inventario_id;
        END IF;

        UPDATE inventario
        SET stock_actual = stock_actual + v_detalle.cantidad,
            fecha_actualizacion = CURRENT_TIMESTAMP
        WHERE id = v_inventario_id;

        INSERT INTO movimiento_inventario (
            inventario_id, usuario_id, tipo, cantidad, fecha_hora,
            observaciones, referencia_tipo, referencia_id
        ) VALUES (
            v_inventario_id, p_usuario_id, 'DEVOLUCION',
            v_detalle.cantidad, CURRENT_TIMESTAMP,
            COALESCE(v_detalle.motivo, 'Devolución de producto'),
            'DEVOLUCION', p_devolucion_id
        );
    END LOOP;

    UPDATE devolucion SET estado = 'COMPLETADA' WHERE id = p_devolucion_id;
END;
$procedure$;
CREATE VIEW public."vw_inventario_stock" WITH (security_invoker=true) AS  SELECT i.id AS inventario_id,
    i.sucursal_id,
    s.nombre AS sucursal,
    i.variante_producto_id,
    vp.sku,
    p.id AS producto_id,
    p.nombre AS producto,
    t.id AS talla_id,
    t.nombre AS talla,
    c.id AS color_id,
    c.nombre AS color,
    i.temporada_id,
    te.nombre AS temporada,
    i.stock_actual,
    i.stock_reservado,
    i.stock_actual - i.stock_reservado AS stock_disponible,
    i.fecha_actualizacion
   FROM inventario i
     JOIN sucursal s ON s.id = i.sucursal_id
     JOIN variante_producto vp ON vp.id = i.variante_producto_id
     JOIN producto p ON p.id = vp.producto_id
     JOIN talla t ON t.id = vp.talla_id
     JOIN color c ON c.id = vp.color_id
     JOIN temporada te ON te.id = i.temporada_id;
