CREATE TRIGGER trg_bitacora_orden_compra AFTER INSERT OR DELETE OR UPDATE ON orden_compra FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_bitacora_pago AFTER INSERT OR DELETE OR UPDATE ON pago FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_bitacora_producto AFTER INSERT OR DELETE OR UPDATE ON producto FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_bitacora_reserva AFTER INSERT OR DELETE OR UPDATE ON reserva FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_bitacora_rol AFTER INSERT OR DELETE OR UPDATE ON rol FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_bitacora_sucursal AFTER INSERT OR DELETE OR UPDATE ON sucursal FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_bitacora_usuario AFTER INSERT OR DELETE OR UPDATE ON usuario FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_normalizar_correo_usuario BEFORE INSERT OR UPDATE ON usuario FOR EACH ROW EXECUTE FUNCTION fn_normalizar_correo_usuario();
CREATE TRIGGER trg_bitacora_variante_producto AFTER INSERT OR DELETE OR UPDATE ON variante_producto FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
CREATE TRIGGER trg_normalizar_sku BEFORE INSERT OR UPDATE ON variante_producto FOR EACH ROW EXECUTE FUNCTION fn_normalizar_sku();
CREATE TRIGGER trg_bitacora_venta AFTER INSERT OR DELETE OR UPDATE ON venta FOR EACH ROW EXECUTE FUNCTION fn_registrar_bitacora();
